ORIGINAL_REVIEWED_BANK_FILE_SHA256 = '55cae68a3cbf12d2b9813ba62d22c70dedd15471869a6aa2646910922a55147f'

def digest(value):
    return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')).hexdigest()

def word_key(word):
    return unicodedata.normalize('NFC', word).casefold()

def board_digest(board):
    return digest({key: board.get(key) for key in ('difficulty', 'rows', 'cols', 'letters', 'mask', 'answers', 'lengths')})

def restore(root):
    folder = root / 'content/gen6/free-refresh-300'
    report_path = folder / 'editorial-review.json'
    report = json.loads(json.dumps(RECORDED_REVIEW, ensure_ascii=False))
    expected = report.pop('_reviewedBoardHashes')
    notes = report.pop('_individualNotes')
    bank_path = folder / 'bank.json'
    bank = json.loads(bank_path.read_text(encoding='utf-8'))
    lexicon_path = root / 'content/lexicon-v3/working/lexicon.json'
    lexicon = json.loads(lexicon_path.read_text(encoding='utf-8'))
    entries = {word_key(e['word']): e for e in lexicon['entries']}

    assert len(bank['boards']) == 300
    assert bank['contentHash'] == report['bankContentHash'] == digest(bank['boards'])
    actual = {board['id']: board_digest(board) for board in bank['boards']}
    assert actual == expected, 'A board changed after the original composition review'
    assert collections.Counter(board['difficulty'] for board in bank['boards']) == {'easy': 100, 'medium': 100, 'hard': 100}
    lexicon_hash = hashlib.sha256(lexicon_path.read_bytes()).hexdigest()
    assert lexicon_hash == '7baff6af094af0331d379050a680980e9b4f880428efd0c9ea620ce80c1fc277'
    report['bankFileSha256'] = hashlib.sha256(bank_path.read_bytes()).hexdigest()
    report['lexiconSha256'] = lexicon_hash
    report['boardContentHashDefinition'] = {'fields': ['difficulty', 'rows', 'cols', 'letters', 'mask', 'answers', 'lengths'], 'serialization': 'UTF-8 JSON, ensure_ascii=false, sort_keys=true, separators=(comma,colon)', 'algorithm': 'sha256', 'excludes': 'presentation and manufacture metadata'}
    report['reviewRecords'] = []
    common_notes = {
        'easy': 'Celá sestava přečtena a redakčně přijata jako krátká běžná slova pro Snadnou; bez zjevného nepatřičného odborného nebo variantního shluku.',
        'medium': 'Celá sestava přečtena a redakčně přijata jako směs známých opor a konkrétnějších slov pro Střední; bez zjevného variantního shluku.',
        'hard': 'Celá sestava přečtena a redakčně přijata pro Těžkou; náročnější výrazy mají konkrétní opory a neskládají pouze úzký odborný nebo úřední výčet.'
    }
    for board in sorted(bank['boards'], key=lambda b: (('easy', 'medium', 'hard').index(b['difficulty']), b['id'])):
        words = [answer['word'] for answer in board['answers']]
        es = [entries[word_key(word)] for word in words]
        assert all(e['target_eligible'] for e in es)
        tiers = dict(collections.Counter(e['tier'] for e in es))
        families = [e.get('family') or word_key(word) for word, e in zip(words, es)]
        assert len(families) == len(set(families))
        record = {
            'boardId': board['id'],
            'difficulty': board['difficulty'],
            'runtimeLevel': board['meta']['level'],
            'boardContentHash': actual[board['id']],
            'decision': 'accepted-ai-composition-review',
            'targetWordsRead': words,
            'tierMixInherited': tiers,
            'topicLabelsInherited': sorted({e['capacity_topic'] for e in es}),
            'newV3Words': [word for word, e in zip(words, es) if e['source_cohort'] == 'approved-expansion-1143'],
            'familyMetadataDuplicates': False,
            'note': notes.get(board['id'], common_notes[board['difficulty']]),
            'individualNote': board['id'] in notes,
            'humanPlaytest': False,
            'userApprovedThisBoard': False,
            'openBlockingIssues': []
        }
        report['reviewRecords'].append(record)
    # Canonical content is identical; an OS newline difference may change bytes.
    # Preserve that difference explicitly rather than inventing byte equivalence.
    if report['bankFileSha256'] != ORIGINAL_REVIEWED_BANK_FILE_SHA256:
        report['recoveryProvenance'] = {
            'originalReviewedBankFileSha256': ORIGINAL_REVIEWED_BANK_FILE_SHA256,
            'canonicalBankAndAll300BoardHashesVerifiedIdentical': True,
            'scope': 'Restored original editorial decisions; bank JSON byte serialization differs from the local reviewed artifact.',
            'newEditorialReviewPerformed': False
        }
    report_path.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    print(json.dumps({'written': str(report_path), 'reviewed': len(report['reviewRecords']), 'bankContentHash': report['bankContentHash'], 'bankFileSha256': report['bankFileSha256'], 'individuallyCommented': sum(r['individualNote'] for r in report['reviewRecords'])}, ensure_ascii=False))
    return report

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--root', type=pathlib.Path, default=pathlib.Path(__file__).resolve().parents[2])
    args = parser.parse_args()
    restore(args.root)

if __name__ == '__main__':
    main()
